BEGIN;
DO $$DECLARE u uuid;v uuid;adm uuid;sid uuid;mid uuid;reg text;pool uuid;dropid uuid;req uuid:=gen_random_uuid();j jsonb;before_n bigint;fixture bigint;oldflag jsonb;flagkey text;BEGIN
 SELECT id INTO adm FROM public.profiles WHERE NOT coalesce(banned,false)AND id IN(SELECT user_id FROM public.admins)LIMIT 1;
 IF adm IS NULL THEN SELECT id INTO adm FROM public.profiles WHERE NOT coalesce(banned,false)AND username='speed';END IF;
 SELECT id INTO u FROM public.profiles WHERE NOT coalesce(banned,false)AND id NOT IN(SELECT user_id FROM public.admins)ORDER BY id LIMIT 1;
 SELECT id INTO v FROM public.profiles WHERE NOT coalesce(banned,false)AND id<>u AND id NOT IN(SELECT user_id FROM public.admins)ORDER BY id LIMIT 1;
 IF u IS NULL OR v IS NULL OR adm IS NULL THEN RAISE EXCEPTION 'Need nonbanned fixture users.';END IF;
 PERFORM set_config('request.jwt.claim.sub',u::text,true);
 BEGIN PERFORM public.xr_live_gift_send('testvideo11','rose',req);RAISE EXCEPTION 'FAIL disabled gift allowed';EXCEPTION WHEN sqlstate '55000'THEN NULL;END;
 BEGIN PERFORM public.xr_clan_fund_contribute(gen_random_uuid(),1,req);RAISE EXCEPTION 'FAIL disabled fund allowed';EXCEPTION WHEN sqlstate '55000'THEN NULL;END;
 IF(public.xr_spend_status()->>'release_authorized')::boolean THEN RAISE EXCEPTION 'FAIL released by migration';END IF;
 IF has_table_privilege('authenticated','public.xr_live_gift_events','INSERT')OR has_table_privilege('anon','public.xr_prediction_choices','SELECT')OR has_function_privilege('authenticated','public.xr_spend_assert(text)','EXECUTE')THEN RAISE EXCEPTION 'FAIL permission boundary';END IF;
 UPDATE public.xr_spend_settings SET release_authorized=true,gifts_enabled=true,predictions_enabled=true,drops_enabled=true,clan_fund_enabled=true,gift_mode='transfer',prediction_result_source='owner_confirmed_match_result',clan_fund_policy='leader_member_rewards_keep_on_leave';
 INSERT INTO public.site_settings(key,value)VALUES('youtube_live','{"active":true,"video_id":"testvideo11","tournament_id":"XR - S2"}')ON CONFLICT(key)DO UPDATE SET value=EXCLUDED.value;
 UPDATE public.xr_live_growth_settings SET video_id='testvideo11',host_user_id=v;
 INSERT INTO public.points_ledger(user_id,delta,kind)VALUES(u,2500,'spend_trial_fixture')RETURNING id INTO fixture;
 -- Fixture reclassification is PRIVATE, transaction-only test setup, not a production award path.
 UPDATE public.xr_wallet_allocations SET earned_delta=2500,unverified_delta=0 WHERE ledger_id=fixture;
 UPDATE public.xr_wallet_accounts SET earned=earned+2500,unverified=unverified-2500 WHERE user_id=u;
 SELECT count(*)INTO before_n FROM public.points_ledger;
 j:=public.xr_live_gift_send('testvideo11','rose',req);IF j->>'ok'<>'true'THEN RAISE EXCEPTION 'FAIL gift %',j;END IF;
 j:=public.xr_live_gift_send('testvideo11','rose',req);IF j->>'already'<>'true'OR(SELECT count(*)FROM public.points_ledger)<>before_n+2 THEN RAISE EXCEPTION 'FAIL idempotency %',j;END IF;
 j:=public.xr_live_gift_send('testvideo11','fire',req);IF j->>'ok'<>'false'THEN RAISE EXCEPTION 'FAIL idempotency mismatch';END IF;
 j:=public.xr_live_gift_send('testvideo11','fake',gen_random_uuid());IF j->>'ok'<>'false'THEN RAISE EXCEPTION 'FAIL catalog';END IF;
 SELECT squad_id INTO sid FROM public.squad_members WHERE user_id=u LIMIT 1;
 IF sid IS NULL THEN INSERT INTO public.squads(name,tag,captain)VALUES('Spend trial','SPT',u)RETURNING id INTO sid;INSERT INTO public.squad_members(squad_id,user_id,role)VALUES(sid,u,'captain');END IF;
 req:=gen_random_uuid();j:=public.xr_clan_fund_contribute(sid,100,req);IF j->>'ok'<>'true'THEN RAISE EXCEPTION 'FAIL contribution %',j;END IF;
 j:=public.xr_clan_fund_contribute(sid,100,req);IF j->>'already'<>'true'THEN RAISE EXCEPTION 'FAIL contribution duplicate';END IF;
 PERFORM set_config('request.jwt.claim.sub',v::text,true);
 BEGIN PERFORM public.xr_clan_fund_get(sid);RAISE EXCEPTION 'FAIL private fund';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.xr_prediction_open_admin(gen_random_uuid(),'testvideo11',clock_timestamp()+interval '1 minute');RAISE EXCEPTION 'FAIL admin authorization';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',adm::text,true);
 SELECT id INTO mid FROM public.matches WHERE tournament_id='XR - S2'ORDER BY starts_at LIMIT 1;
 SELECT id INTO reg FROM public.registrations WHERE tournament_id='XR - S2'AND status='confirmed'AND verified AND NOT coalesce(hold,false)LIMIT 1;
 j:=public.xr_prediction_open_admin(mid,'testvideo11',clock_timestamp()+interval '1 minute');IF j->>'ok'<>'true'THEN RAISE EXCEPTION 'FAIL pool open %',j;END IF;pool:=(j->>'pool_id')::uuid;
 PERFORM set_config('request.jwt.claim.sub',u::text,true);j:=public.xr_prediction_choose(pool,reg);IF j->>'ok'<>'true'THEN RAISE EXCEPTION 'FAIL choice %',j;END IF;
 j:=public.xr_prediction_choose(pool,reg);IF j->>'ok'<>'true'THEN RAISE EXCEPTION 'FAIL repeatedchoice';END IF;
 PERFORM set_config('request.jwt.claim.sub',adm::text,true);
 j:=public.xr_prediction_settle_admin(pool,reg,'Real match result owner-approved fixture');IF j->>'ok'<>'false'THEN RAISE EXCEPTION 'FAIL early settlement';END IF;
 UPDATE public.matches SET status='done'WHERE id=mid;UPDATE public.xr_prediction_pools SET closes_at=clock_timestamp()-interval '1 minute'WHERE id=pool;
 j:=public.xr_prediction_settle_admin(pool,reg,'Real match result owner-approved fixture');IF j->>'ok'<>'true'OR(j->>'rewarded')::int<>1 THEN RAISE EXCEPTION 'FAIL settlement %',j;END IF;
 j:=public.xr_prediction_settle_admin(pool,reg,'Real match result owner-approved fixture');IF j->>'already'<>'true'THEN RAISE EXCEPTION 'FAIL duplicate settlement %',j;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.xr_prediction_choices c JOIN public.xr_wallet_allocations a ON a.ledger_id=c.ledger_id WHERE c.pool_id=pool AND a.earned_delta=200)THEN RAISE EXCEPTION 'FAIL prediction provenance';END IF;
 IF EXISTS(SELECT 1 FROM public.xr_wallet_accounts a WHERE a.earned+a.granted+a.unverified<>(SELECT coalesce(sum(delta),0)FROM public.points_ledger p WHERE p.user_id=a.user_id))THEN RAISE EXCEPTION 'FAIL balance reconciliation';END IF;
END $$;
SELECT 'PASS disabled defaults, auth, privacy, gift/contribution idempotency, catalog, prediction result gate, payout once, provenance and reconciliation'AS test_result;
DO $$DECLARE adm uuid;u uuid;v uuid;sid uuid;did uuid;d jsonb;rec record;c integer:=0;before_n bigint;req uuid;BEGIN
 SELECT a.user_id INTO adm FROM public.admins a JOIN public.profiles p ON p.id=a.user_id WHERE NOT coalesce(p.banned,false)LIMIT 1;
 SELECT id INTO u FROM public.profiles WHERE NOT coalesce(banned,false)AND id NOT IN(SELECT user_id FROM public.admins)ORDER BY id LIMIT 1;
 SELECT id INTO v FROM public.profiles WHERE NOT coalesce(banned,false)AND id<>u AND id NOT IN(SELECT user_id FROM public.admins)ORDER BY id LIMIT 1;
 PERFORM set_config('request.jwt.claim.sub',adm::text,true);
 d:=public.xr_live_drop_open_admin('testvideo11',clock_timestamp()+interval '15 minutes');IF d->>'ok'<>'true'THEN RAISE EXCEPTION 'FAIL drop open %',d;END IF;did:=(d->>'drop_id')::uuid;
 FOR rec IN SELECT id FROM public.profiles WHERE NOT coalesce(banned,false)ORDER BY id LIMIT 12 LOOP
 INSERT INTO public.live_tournament_posts(tournament_id,user_id,body,created_at)VALUES('XR - S2',rec.id,'GG WP',clock_timestamp());
 INSERT INTO public.live_tournament_posts(tournament_id,user_id,body,created_at)VALUES('XR - S2',rec.id,'BOOYAH',clock_timestamp());c:=c+1;
 END LOOP;
 IF(SELECT count(*)FROM public.xr_drop_claims WHERE drop_id=did)<>least(10,c)THEN RAISE EXCEPTION 'FAIL drop unique/cap';END IF;
 IF EXISTS(SELECT 1 FROM public.xr_drop_claims cl JOIN public.xr_wallet_allocations a ON a.ledger_id=cl.ledger_id WHERE cl.drop_id=did AND a.earned_delta<>50)THEN RAISE EXCEPTION 'FAIL drop provenance';END IF;
 SELECT count(*)INTO before_n FROM public.xr_drop_claims;
 INSERT INTO public.live_tournament_posts(tournament_id,user_id,body,hidden,created_at)VALUES('XR - S2',u,'hidden',true,clock_timestamp());
 INSERT INTO public.live_tournament_posts(tournament_id,user_id,body,created_at)VALUES('xr-s1',u,'wrong tournament',clock_timestamp());
 IF(SELECT count(*)FROM public.xr_drop_claims)<>before_n THEN RAISE EXCEPTION 'FAIL ineligible comments';END IF;
 SELECT squad_id INTO sid FROM public.squad_members WHERE user_id=u;
 -- Trial clan from first block may have existing captain; make fixture member leader transactionally.
 UPDATE public.squads SET captain=u WHERE id=sid;
 IF NOT EXISTS(SELECT 1 FROM public.squad_members WHERE user_id=v AND squad_id=sid)THEN DELETE FROM public.squad_members WHERE user_id=v;INSERT INTO public.squad_members(squad_id,user_id,role)VALUES(sid,v,'member');END IF;
 PERFORM set_config('request.jwt.claim.sub',v::text,true);
 BEGIN PERFORM public.xr_clan_fund_reward(sid,u,10,gen_random_uuid());RAISE EXCEPTION 'FAIL member fund spend';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',u::text,true);req:=gen_random_uuid();
 d:=public.xr_clan_fund_reward(sid,v,25,req);IF d->>'ok'<>'true'THEN RAISE EXCEPTION 'FAIL leader fund spend %',d;END IF;
 d:=public.xr_clan_fund_reward(sid,v,25,req);IF d->>'already'<>'true'THEN RAISE EXCEPTION 'FAIL fund repeat';END IF;
 d:=public.xr_clan_fund_reward(sid,v,100,gen_random_uuid());IF d->>'ok'<>'false'THEN RAISE EXCEPTION 'FAIL fund overspend';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.xr_clan_fund_distributions d JOIN public.xr_wallet_allocations a ON a.ledger_id=d.ledger_id WHERE d.squad_id=sid AND a.granted_delta=25)THEN RAISE EXCEPTION 'FAIL fund gifted bucket';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.xr_live_gift_events e JOIN public.xr_wallet_allocations a ON a.ledger_id=e.credit_ledger WHERE e.user_id=u AND a.granted_delta=10)THEN RAISE EXCEPTION 'FAIL gifted receipt earned-washed';END IF;
 d:=public.xr_clan_fund_get(sid);IF jsonb_array_length(d->'members')<2 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d->'members')m WHERE m->>'id'=v::text AND nullif(m->>'name','')IS NOT NULL)THEN RAISE EXCEPTION 'FAIL current member roster';END IF;IF(d->>'balance')::integer<>75 THEN RAISE EXCEPTION 'FAIL fund balance %',d;END IF;
 DELETE FROM public.squad_members WHERE squad_id=sid AND user_id=v;
 IF(SELECT coalesce(sum(amount),0)FROM public.xr_clan_fund_entries WHERE squad_id=sid)<>100 THEN RAISE EXCEPTION 'FAIL leave mutation';END IF;
 d:=public.xr_clan_fund_reward(sid,v,10,gen_random_uuid());IF d->>'ok'<>'false'THEN RAISE EXCEPTION 'FAIL ex-member reward';END IF;
 IF EXISTS(SELECT 1 FROM public.xr_wallet_accounts a WHERE a.earned+a.granted+a.unverified<>(SELECT coalesce(sum(delta),0)FROM public.points_ledger p WHERE p.user_id=a.user_id))THEN RAISE EXCEPTION 'FAIL final reconciliation';END IF;
END $$;
SELECT 'PASS first10 unique eligible live commenters, duplicate/cap, hidden/wrong-stream, 50AP certified reward, leader-only current-member fund reward, idempotency, fund overspend, gifted provenance, no leave refund, final reconciliation'AS test_result;

ROLLBACK;